def dump(rel,data):
    p=ROOT/rel
    if p.exists():raise SystemExit(f'기존 원장 보존: {p}')
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')

def main():
    cases=[]
    for no,country,title,operator,stage,event,ai,src,biz,relation,lesson in CASES:
        cases.append(dict(id='CASE-'+no,country=country,title=title,operator=operator,deployment_stage=stage,event_date=event,ai_evidence=ai,source_ids=['DRS-'+x for x in src],candidate_ids=['TS-BIZ-'+x for x in biz],comparability=relation,application_judgment=lesson,cost=None,independent_effect_verified=False,checked_at='2026-09-09',version='0.1',supersedes=None))
    dump('03_도입사례/사례원장.json',{'schema_version':'1.0','cases':cases})
    sols=[]
    for no,name,biz,cs,flow,si,ai,gate in SOLUTIONS:
        sols.append(dict(id='SOL-'+no,name=name,candidate_ids=['TS-BIZ-'+x for x in biz],case_ids=['CASE-'+x for x in cs],flow=flow,si_baseline=si,ai_option=ai,acceptance_gate=gate,status='기획 대안·제품 선정 아님'))
    dump('02_공통솔루션/솔루션원장.json',{'schema_version':'1.0','solutions':sols})
    portfolio=json.loads((ROOT.parent/'05_통합사업기획/사업포트폴리오.json').read_text(encoding='utf-8'))
    base={x['id']:x for x in portfolio['candidates']}
    subjects=[]
    for x in DETAILS:
        x=dict(x);no=x.pop('no');cid='TS-BIZ-'+no
        x.update(id=cid,problem_id='PRB-'+no,name=base[cid]['name'],folder=cid+'_'+x.pop('short'),source_ids=['DRS-'+v for v in x.pop('sources')],case_ids=['CASE-'+v for v in x.pop('cases')],solution_ids=['SOL-'+v for v in x.pop('solutions')],mandate_ids=base[cid]['mandate_ids'],nature=base[cid]['nature'],status='상세 조사 초안·현장 검증 전',problem_status='가설·규모와 원인 추가 검증',selected=False,budget_krw=None,checked_at='2026-09-09',version='0.1')
        subjects.append(x)
    dump('01_후보별/후보분석_원장.json',{'schema_version':'1.0','subjects':subjects})
    print(f'후보 {len(subjects)}개, 사례 {len(cases)}개, 솔루션 유형 {len(sols)}개')

if __name__=='__main__':main()
